create or replace function public.get_hr_employees_workspace_v1(p_identity_id uuid,p_tenant_id bigint,p_branch_id bigint,p_search text default null,p_state text default null,p_page integer default 1,p_page_size integer default 40) returns jsonb language plpgsql stable set search_path to '' as $fn$
declare v_membership bigint;v_can_manage boolean:=false;v_total bigint;v_rows jsonb;v_summary jsonb;v_date date:=public.institution_local_date(p_tenant_id);v_offset integer:=greatest(coalesce(p_page,1)-1,0)*least(greatest(coalesce(p_page_size,40),1),100);
begin
select m.id,exists(select 1 from public.membership_roles mr join public.role_permissions rp on rp.tenant_id=mr.tenant_id and rp.role_id=mr.role_id where mr.tenant_id=m.tenant_id and mr.membership_id=m.id and rp.permission_code='hr.employee.manage') into v_membership,v_can_manage from public.memberships m where m.tenant_id=p_tenant_id and m.identity_id=p_identity_id and m.status='active' and (m.all_branches or exists(select 1 from public.membership_branch_scopes s where s.tenant_id=m.tenant_id and s.membership_id=m.id and s.branch_id=p_branch_id)) and exists(select 1 from public.membership_roles mr join public.role_permissions rp on rp.tenant_id=mr.tenant_id and rp.role_id=mr.role_id where mr.tenant_id=m.tenant_id and mr.membership_id=m.id and rp.permission_code='hr.employee.read') order by m.created_at limit 1;
if v_membership is null then raise exception 'employee read permission denied'; end if;
select count(*) into v_total from public.hr_employments e join public.persons p on p.tenant_id=e.tenant_id and p.id=e.employee_person_id where e.tenant_id=p_tenant_id and e.branch_id=p_branch_id and (p_state is null or p_state='' or e.state=p_state) and (p_search is null or btrim(p_search)='' or p.display_name ilike '%'||btrim(p_search)||'%' or e.employee_number ilike '%'||btrim(p_search)||'%' or coalesce(e.department_key,'') ilike '%'||btrim(p_search)||'%' or e.designation_key ilike '%'||btrim(p_search)||'%');
select coalesce(jsonb_agg(to_jsonb(x) order by x.display_name),'[]'::jsonb) into v_rows from (select e.id employment_id,e.employee_person_id person_id,e.employee_number,p.display_name,p.name_native,e.department_key,e.designation_key,e.contract_type,e.starts_on,e.ends_on,e.payroll_eligible,e.state,ar.status attendance_today,ar.check_in_at,ar.check_out_at,ar.source attendance_source,(select count(*) from public.hr_leave_requests lr where lr.tenant_id=e.tenant_id and lr.employment_id=e.id and lr.state='submitted') pending_leave_requests from public.hr_employments e join public.persons p on p.tenant_id=e.tenant_id and p.id=e.employee_person_id left join public.hr_effective_attendance_v1 ar on ar.tenant_id=e.tenant_id and ar.employment_id=e.id and ar.attendance_date=v_date where e.tenant_id=p_tenant_id and e.branch_id=p_branch_id and (p_state is null or p_state='' or e.state=p_state) and (p_search is null or btrim(p_search)='' or p.display_name ilike '%'||btrim(p_search)||'%' or e.employee_number ilike '%'||btrim(p_search)||'%' or coalesce(e.department_key,'') ilike '%'||btrim(p_search)||'%' or e.designation_key ilike '%'||btrim(p_search)||'%') order by p.display_name,e.id limit least(greatest(coalesce(p_page_size,40),1),100) offset v_offset) x;
select jsonb_build_object('total',count(*),'active',count(*) filter(where state='active'),'on_leave',count(*) filter(where state='on_leave'),'attendance_marked_today',(select count(*) from public.hr_effective_attendance_v1 ar join public.hr_employments he on he.tenant_id=ar.tenant_id and he.id=ar.employment_id where ar.tenant_id=p_tenant_id and he.branch_id=p_branch_id and ar.attendance_date=v_date),'leave_pending',(select count(*) from public.hr_leave_requests lr join public.hr_employments he on he.tenant_id=lr.tenant_id and he.id=lr.employment_id where lr.tenant_id=p_tenant_id and he.branch_id=p_branch_id and lr.state='submitted')) into v_summary from public.hr_employments where tenant_id=p_tenant_id and branch_id=p_branch_id;
return jsonb_build_object('local_date',v_date,'summary',v_summary,'total',v_total,'page',greatest(coalesce(p_page,1),1),'page_size',least(greatest(coalesce(p_page_size,40),1),100),'can_manage',v_can_manage,'rows',v_rows);end;$fn$;

create or replace function public.get_hr_attendance_workspace_v1(p_identity_id uuid,p_tenant_id bigint,p_branch_id bigint,p_attendance_date date default null,p_search text default null) returns jsonb language plpgsql stable set search_path to '' as $fn$
declare v_membership bigint;v_can_manage boolean:=false;v_date date:=coalesce(p_attendance_date,public.institution_local_date(p_tenant_id));v_rows jsonb;v_summary jsonb;
begin
select m.id,exists(select 1 from public.membership_roles mr join public.role_permissions rp on rp.tenant_id=mr.tenant_id and rp.role_id=mr.role_id where mr.tenant_id=m.tenant_id and mr.membership_id=m.id and rp.permission_code='hr.employee.manage') into v_membership,v_can_manage from public.memberships m where m.tenant_id=p_tenant_id and m.identity_id=p_identity_id and m.status='active' and (m.all_branches or exists(select 1 from public.membership_branch_scopes s where s.tenant_id=m.tenant_id and s.membership_id=m.id and s.branch_id=p_branch_id)) and exists(select 1 from public.membership_roles mr join public.role_permissions rp on rp.tenant_id=mr.tenant_id and rp.role_id=mr.role_id where mr.tenant_id=m.tenant_id and mr.membership_id=m.id and rp.permission_code='hr.employee.read') order by m.created_at limit 1;
if v_membership is null then raise exception 'staff attendance read permission denied'; end if;
select coalesce(jsonb_agg(to_jsonb(x) order by x.display_name),'[]'::jsonb) into v_rows from (select e.id employment_id,e.employee_person_id person_id,e.employee_number,p.display_name,p.name_native,e.department_key,e.designation_key,e.state employment_state,a.id attendance_record_id,coalesce(a.status,'unmarked') status,a.check_in_at,a.check_out_at,a.source,a.latest_correction_id,a.correction_reason from public.hr_employments e join public.persons p on p.tenant_id=e.tenant_id and p.id=e.employee_person_id left join public.hr_effective_attendance_v1 a on a.tenant_id=e.tenant_id and a.employment_id=e.id and a.attendance_date=v_date where e.tenant_id=p_tenant_id and e.branch_id=p_branch_id and e.state in ('active','on_leave','suspended') and (p_search is null or btrim(p_search)='' or p.display_name ilike '%'||btrim(p_search)||'%' or e.employee_number ilike '%'||btrim(p_search)||'%')) x;
select jsonb_build_object('total',count(*),'marked',count(*) filter(where a.id is not null),'present',count(*) filter(where a.status='present'),'absent',count(*) filter(where a.status='absent'),'late',count(*) filter(where a.status='late'),'leave',count(*) filter(where a.status='leave'),'unmarked',count(*) filter(where a.id is null)) into v_summary from public.hr_employments e left join public.hr_effective_attendance_v1 a on a.tenant_id=e.tenant_id and a.employment_id=e.id and a.attendance_date=v_date where e.tenant_id=p_tenant_id and e.branch_id=p_branch_id and e.state in ('active','on_leave','suspended');
return jsonb_build_object('date',v_date,'summary',v_summary,'rows',v_rows,'can_manage',v_can_manage);end;$fn$;

create or replace function public.get_hr_leave_workspace_v1(p_identity_id uuid,p_tenant_id bigint,p_branch_id bigint,p_state text default null) returns jsonb language plpgsql stable set search_path to '' as $fn$
declare v_membership bigint;v_can_manage boolean:=false;v_types jsonb;v_rows jsonb;
begin
select m.id,exists(select 1 from public.membership_roles mr join public.role_permissions rp on rp.tenant_id=mr.tenant_id and rp.role_id=mr.role_id where mr.tenant_id=m.tenant_id and mr.membership_id=m.id and rp.permission_code='hr.employee.manage') into v_membership,v_can_manage from public.memberships m where m.tenant_id=p_tenant_id and m.identity_id=p_identity_id and m.status='active' and (m.all_branches or exists(select 1 from public.membership_branch_scopes s where s.tenant_id=m.tenant_id and s.membership_id=m.id and s.branch_id=p_branch_id)) and exists(select 1 from public.membership_roles mr join public.role_permissions rp on rp.tenant_id=mr.tenant_id and rp.role_id=mr.role_id where mr.tenant_id=m.tenant_id and mr.membership_id=m.id and rp.permission_code='hr.employee.read') order by m.created_at limit 1;
if v_membership is null then raise exception 'leave read permission denied'; end if;
select coalesce(jsonb_agg(jsonb_build_object('id',lt.id,'key',lt.key,'labels',lt.labels,'payroll_effect',lt.payroll_effect) order by lt.key),'[]'::jsonb) into v_types from public.hr_leave_types lt where lt.tenant_id=p_tenant_id and lt.state='active';
select coalesce(jsonb_agg(to_jsonb(x) order by x.starts_on desc,x.id desc),'[]'::jsonb) into v_rows from (select lr.id,lr.employment_id,e.employee_person_id person_id,e.employee_number,p.display_name,lr.leave_type_id,lt.key leave_type_key,lt.labels leave_type_labels,lr.starts_on,lr.ends_on,lr.requested_units,lr.reason,lr.state,lr.decided_at,lr.decision_reason from public.hr_leave_requests lr join public.hr_employments e on e.tenant_id=lr.tenant_id and e.id=lr.employment_id join public.persons p on p.tenant_id=e.tenant_id and p.id=e.employee_person_id join public.hr_leave_types lt on lt.tenant_id=lr.tenant_id and lt.id=lr.leave_type_id where lr.tenant_id=p_tenant_id and e.branch_id=p_branch_id and (p_state is null or p_state='' or lr.state=p_state)) x;
return jsonb_build_object('leave_types',v_types,'rows',v_rows,'can_manage',v_can_manage);end;$fn$;